#include <stdio.h>
#include <stdbool.h>

int main(void) {
    int N, C;
    if (scanf("%d %d", &N, &C) != 2) return 0;

    bool infectedByHuman[N + 1];
    for (int i = 1; i <= N; i++) {
        infectedByHuman[i] = false;
    }

    for (int c = 0; c < C; c++) {
        int P, I;
        scanf("%d %d", &P, &I);

        for (int i = 0; i < I; i++) {
            int x;
            scanf("%d", &x);
            infectedByHuman[x] = true;
        }
    }

    for (int i = 1; i <= N; i++) {
        if (!infectedByHuman[i]) {
            printf("%d\n", i);
        }
    }

    return 0;
}
